/**
 * Maps one Recently Viewed recommendation onto the subset of `ZimmProductCard` props the
 * `recentlyViewed` variation (SFCC-83) actually renders.
 *
 * Input is exactly what `use-einstein.js`'s `fetchRecProductDetails` produces (search that name
 * in `node_modules/@salesforce/retail-react-app/app/hooks/use-einstein.js`): an Einstein rec
 * merged with its matching Commerce API product, fetched via `getProducts` with `expand:
 * ['availability', 'links', 'promotions', 'options', 'images', 'prices', 'variations']` —
 * `{...rec, ...product, productId: rec.id, image: {disBaseLink: rec.imageUrl, alt:
 * rec.productName}}`.
 *
 * Modelled on `overrides/app/pages/product-detail/productInfo.ts` — no React/react-intl import,
 * `formatPrice` injected as a parameter so this module stays independently testable — and on the
 * general shape of `liveProductCardDemoMapper.ts` (`feature/zimmproductcard-live-demo`, not this
 * branch — read for its approach, not imported). Unlike that demo mapper, this is a production
 * path: real `commerce-sdk-isomorphic` SDK types are used wherever they exist (AGENTS.md > Type
 * Definitions), and only the two fields the SDK doesn't export (`productId`, the flat Einstein
 * `image`) are hand-rolled, each with its own why-comment below.
 *
 * Deliberately narrow scope, stated here rather than left as a silent gap: this mapper only ever
 * returns `currentPrice` (an active selling price). It does not attempt was/now sale-price
 * detection (`originalPrice`) — that needs `getPriceData`-style pricebook logic
 * (`productInfo.ts`'s own `PdpSourcePrice`) that this merged Einstein shape has no equivalent of,
 * and the `recentlyViewed` variation renders no price at all today (see
 * `zimmProductCard/index.tsx`'s `recentlyViewed` `VARIATION_CONFIG` row — `showContent: false`).
 * Mapping `currentPrice` anyway costs nothing and means a future consumer of this same mapper
 * (e.g. a variation that does render price) isn't blocked on this file being revisited.
 */
import type { ShopperProductsTypes } from 'commerce-sdk-isomorphic';
import { filterImageGroups } from '@salesforce/retail-react-app/app/utils/product-utils';
import { productUrlBuilder } from '@salesforce/retail-react-app/app/utils/url';
import type { ZimmProductCardBaseProps, ZimmProductCardImage } from '../components/ui-kits/organisms/zimmProductCard';

/**
 * The real Commerce API `Product` (`commerce-sdk-isomorphic`'s own `ShopperProductsTypes.Product`
 * — not hand-rolled), plus the two fields `fetchRecProductDetails` bolts on that have no SDK
 * equivalent:
 */
export type RecentlyViewedProduct = ShopperProductsTypes.Product & {
  /** Set by `fetchRecProductDetails` to `rec.id`. Guaranteed present and equal to `Product.id`
   *  for every entry that function produces (it already filters out any rec with no matching
   *  product before this shape exists at all) — read this rather than `.id` only because it's
   *  the field the real runtime hook explicitly produces this way. */
  productId: string;
  /** The same function's own quick single-reference image (Einstein's own `rec.imageUrl`/
   *  `rec.productName`), distinct from the full product's own `imageGroups` array below — used
   *  as a fallback only when `imageGroups` filtering comes up empty. See `selectPrimaryImage`. */
  image?: { disBaseLink?: string; alt?: string };
};

/** Formats a bare amount for the storefront. Injected so this module stays free of react-intl,
 *  mirroring `productInfo.ts`'s own `FormatPrice` shape. */
export type FormatPrice = (amount: number, currency: string) => string;

/**
 * The subset of `ZimmProductCardBaseProps` this mapper populates. Deliberately excludes
 * `headingLevel` and `variation` — both are render-context decisions belonging to the rail
 * organism that consumes this mapper's output (SFCC-83's A5 step), which supplies `headingLevel`
 * uniformly for every card it renders and adds `variation: 'recentlyViewed'` itself when
 * spreading this output into `<ZimmProductCard>`. A pure data mapper choosing a heading level
 * would conflate a data concern with a layout one. Also excludes `hoverImage`/`images` — this
 * mapper only ever returns one image (`primaryImage`); see `selectPrimaryImage`'s own docblock
 * for why.
 */
export type RecentlyViewedCard = Pick<
  ZimmProductCardBaseProps,
  'id' | 'href' | 'name' | 'primaryImage' | 'currentPrice'
>;

/** The correctly-sized product image view, per AGENTS.md's image-sizing guidance: never serve an
 *  arbitrary-sized image at thumbnail size. Named rather than inlined per conventions.md's
 *  no-magic-strings rule — this is a real, semantic SFCC image `viewType` key. */
const MEDIUM_VIEW_TYPE = 'medium';

/**
 * Resolves the one image this mapper ever returns. `hoverImage`/`images` are never populated —
 * SFCC-83 AC 3 asks for "the product's index image" (singular), and the `recentlyViewed`
 * variation renders neither a hover-swap nor a gallery (see `zimmProductCard/index.tsx`'s
 * `recentlyViewed` row: `showHoverImageSwap: false`, and its render branch never forwards
 * `images` at all).
 *
 * Prefers `filterImageGroups` at `viewType: 'medium'` (a real, correctly-sized product image) —
 * `variationValues` is deliberately empty: a Recently Viewed rec is already one specific product,
 * not a search hit needing a variant pick the way `liveProductCardDemoMapper.ts`'s own
 * `resolveDemoVariant` handles, so that logic does not apply here. Falls back to Einstein's own
 * flat `image` field only when that filtering produces nothing usable — see
 * `RecentlyViewedProduct.image`'s own comment for what that field is.
 *
 * @returns `null` when neither source has a usable `src`. `ZimmProductCardMediaImage.alt` is
 *   required and non-empty, so there is no safe placeholder card to build without a real image —
 *   a card with an invented placeholder `src` would need an asset this codebase has no confirmed
 *   token or precedent for, so "no usable image" is treated the same as "no usable name" in
 *   `selectRecentlyViewedCard` below: a hard gate that yields no card at all. Returning `null`
 *   here is the only option that structurally cannot violate the non-empty-`alt` contract, since
 *   there is no returned object for `alt` to be empty on.
 */
const selectPrimaryImage = (product: RecentlyViewedProduct, productName: string): ZimmProductCardImage | null => {
  const filteredGroups = filterImageGroups(product.imageGroups ?? [], {
    viewType: MEDIUM_VIEW_TYPE,
    variationValues: {},
  }) as ShopperProductsTypes.ImageGroup[];
  const [groupImage] = filteredGroups[0]?.images ?? [];

  const src = groupImage ? groupImage.disBaseLink || groupImage.link : product.image?.disBaseLink;
  if (!src) return null;

  // ZimmProductCardMediaImage.alt is required and non-empty (unlike base ProductTile's
  // decorative alt: '' convention) — mirrors liveProductCardDemoMapper.ts's own fallback exactly.
  const alt = (groupImage ? groupImage.alt : product.image?.alt)?.trim() || productName;
  return { src, alt };
};

/**
 * @param product - The merged Einstein rec + Commerce API product `fetchRecProductDetails`
 *   produces, or `undefined`/`null` while that data is not yet available.
 * @param formatPrice - Currency formatter, normally `intl.formatNumber`.
 * @returns Props for the `recentlyViewed` `ZimmProductCard` variation, or `null` when the rec has
 *   no usable name or no usable image — never a broken card, never a throw.
 */
export const selectRecentlyViewedCard = (
  product: RecentlyViewedProduct | undefined | null,
  formatPrice: FormatPrice,
): RecentlyViewedCard | null => {
  if (!product?.name) return null;

  const primaryImage = selectPrimaryImage(product, product.name);
  if (!primaryImage) return null;

  return {
    // Reads productId, not the SDK Product's own `id` — see RecentlyViewedProduct.productId's
    // own comment for why (guaranteed equal in practice, but productId is the field the real
    // runtime hook explicitly produces this way).
    id: product.productId,
    href: productUrlBuilder({ id: product.productId }),
    name: product.name,
    primaryImage,
    // No hardcoded fallback currency — if either is absent, skip formatting rather than guess,
    // matching productInfo.ts's own "no hardcoded fallback currency" comment.
    currentPrice:
      typeof product.price === 'number' && product.currency ? formatPrice(product.price, product.currency) : undefined,
  };
};

